/// Ponte da API local: só a janela `main` responde pelo app
/// (`capabilities/local-api-bridge.json`). Um overlay que chamasse
/// `local_api_respond` responderia requisições que não executou.
pub const MAIN_ONLY_COMMANDS: &[&str] = &["local_api_respond", "local_api_bridge_ready"];
